use js_runtime::{Runtime,Value,JsResult,EnvId};
fn verify(rt:&mut Runtime,input:&[Option<Value>]){let value=rt.array(input);let id=rt.object_id(value).unwrap();let count=input.iter().flatten().count();assert_eq!(rt.objects[id.0].properties.len(),count);let key=rt.intern("length");assert_eq!(rt.get(value,key).unwrap(),Value::Number(input.len()as f64));for(index,item)in input.iter().enumerate(){let key=rt.index_property_key(index);assert_eq!(rt.has_own_property(value,key).unwrap(),item.is_some());if let Some(expected)=item{let actual=rt.get(value,key).unwrap();match(actual,*expected){(Value::Number(a),Value::Number(b))=>assert_eq!(a.to_bits(),b.to_bits()),_=>assert_eq!(actual,*expected)}}}let keys=rt.own_keys(value,true).unwrap();let expected=input.iter().enumerate().filter_map(|(i,v)|v.map(|_|Value::String(rt.index_property_key(i).0))).collect::<Vec<_>>();assert_eq!(keys,expected);}
#[test]fn dense_sparse_and_all_hole_arrays_keep_exact_keys_order_and_bits(){for enabled in[false,true]{let mut rt=Runtime::new();rt.array_storage_reserve_enabled=enabled;verify(&mut rt,&[]);verify(&mut rt,&[None;128]);verify(&mut rt,&[Some(Value::Number(-0.0)),None,Some(Value::Number(f64::from_bits(0x7ff0000000000042))),None,Some(Value::Undefined)]);let dense=(0..512).map(|i|Some(Value::Number(i as f64))).collect::<Vec<_>>();verify(&mut rt,&dense);}}
fn rounds(rt:&mut Runtime,_:Value,_:&[Value],parent:EnvId)->JsResult<Value>{let env=rt.child_env(parent);for(name,n)in[("battles",23.0),("warmup",0.0),("battleIndex",0.0)]{rt.declare(env,name,Value::Number(n))?;}let initial=rt.objects.len();for round in 0..23{for _ in 0..16{let input=(0..(round+1)).map(|i|if i%3==0{None}else{Some(Value::Number(i as f64))}).collect::<Vec<_>>();verify(rt,&input);}rt.assign(env,"battleIndex",Value::Number(round as f64),false)?;rt.collect_native_battle_backedge(env,parent)?;}assert!(rt.objects.len()<initial+32);Ok(Value::Number(rt.native_battle_gc_stats().collections as f64))}
#[test]fn retained_buffers_reset_cleanly_across_twenty_three_collections(){for enabled in[false,true]{let mut rt=Runtime::new();rt.array_storage_reserve_enabled=enabled;let function=rt.make_closure(rounds,rt.global_env,0,"__nativeRun");rt.set_function_source(function,&include_str!("../src/native_battle_run.js").encode_utf16().collect::<Vec<_>>()).unwrap();rt.enable_native_battle_gc();assert_eq!(rt.call(function,Value::Undefined,&[]).unwrap(),Value::Number(23.0));}}
